package com.company.skillplatform.bundle.application;
import com.company.skillplatform.audit.application.DownloadAuditService;import com.company.skillplatform.bundle.infrastructure.repository.*;import com.company.skillplatform.common.application.BusinessException;import com.company.skillplatform.common.logging.LogContext;import com.company.skillplatform.storage.domain.ObjectStoragePort;import java.io.*;import org.springframework.core.io.ByteArrayResource;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class BundleDownloadService{private static final org.slf4j.Logger log=org.slf4j.LoggerFactory.getLogger(BundleDownloadService.class);private final SkillBundleRepository bundles;private final SkillBundleItemRepository items;private final ObjectStoragePort storage;private final DownloadAuditService audit;public BundleDownloadService(SkillBundleRepository b,SkillBundleItemRepository i,ObjectStoragePort s,DownloadAuditService a){bundles=b;items=i;storage=s;audit=a;}@PreAuthorize("hasAuthority('skill:download')")@Transactional(readOnly=true)public ResponseEntity<ByteArrayResource> download(Long id,Long userId){var b=bundles.findByIdAndCreatedById(id,userId).orElseThrow(()->new BusinessException("BUNDLE_NOT_FOUND","Bundle not found",HttpStatus.NOT_FOUND));if(!"AVAILABLE".equals(b.getStatus()))throw new BusinessException("BUNDLE_NOT_AVAILABLE","Bundle is not available",HttpStatus.NOT_FOUND);try(InputStream in=storage.get(b.getObjectKey())){byte[] bytes=in.readAllBytes();java.util.Set<Long>skills= new java.util.HashSet<>();for(var item:items.findByBundleId(id)){if(skills.add(item.getVersion().getSkill().getId()))audit.record(userId,item.getVersion().getSkill().getId(),null,id,b.getObjectKey());}return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).contentLength(bytes.length).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename="+b.getFileName()).body(new ByteArrayResource(bytes));}catch(IOException e){log.error("event=bundle.download.failed requestId={} actorId={} bundleId={} errorCode={}",LogContext.requestId(),userId,id,"BUNDLE_READ_FAILED",e);throw new BusinessException("BUNDLE_READ_FAILED","Unable to read bundle",HttpStatus.BAD_GATEWAY);}}}
